const adultGroupPattern=/yeti[şs]kin|\+?18\+?|for adults|adult|xxx|erotik|erotic/;
function isAdultGroup(group:string){
  // JS'in /i bayrağı Türkçe büyük İ harfini duzgun kucultmuyor (klasik "Turkish I" sorunu) --
  // İ/I/ı harflerini once elle duz "i"ye ceviriyoruz ki "YETİŞKİN" gibi buyuk harfli gruplar da
  // yakalansın.
  const normalized=(group||"").replace(/[İIı]/g,"i").toLowerCase();
  return adultGroupPattern.test(normalized);
}
function readPlayerPrefs(profileId:string):PlayerPrefs{try{const saved=JSON.parse(localStorage.getItem(profileKey(profileId,"settings"))||"{}");const legacyAudio:Record<string,string>={"Otomatik":"auto","Türkçe":"tr","Orijinal":"original"};return{...defaultPlayerPrefs,...saved,audioLanguage:saved.audioLanguage||(legacyAudio[String(saved.audio||"")]||"auto"),subtitleMode:saved.subtitleMode||(saved.subtitle==="Kapalı"?"off":"auto"),subtitleLanguage:saved.subtitleLanguage||(saved.subtitle==="Türkçe"?"tr":"auto")}}catch{return{...defaultPlayerPrefs}}}
function savePlayerPrefs(profileId:string,prefs:PlayerPrefs){localStorage.setItem(profileKey(profileId,"settings"),JSON.stringify(prefs));window.dispatchEvent(new CustomEvent("slx-playback-settings",{detail:prefs}))}
function readWatchProgress(profileId:string):WatchEntry[]{try{const scoped=localStorage.getItem(profileKey(profileId,"watch-progress"));const rows=JSON.parse(scoped||localStorage.getItem("slx-watch-progress")||"[]");return Array.isArray(rows)?rows:[]}catch{return[]}}
function saveWatchProgress(profileId:string,item:Media,current:number,duration:number){if(item.kind==="live"||!Number.isFinite(duration)||duration<30||!Number.isFinite(current)||current<5)return;const rows=readWatchProgress(profileId).filter(entry=>entry.item.id!==item.id);const next=current/duration>=.95?rows:[{item,current,duration,updatedAt:Date.now()},...rows].slice(0,20);const value=JSON.stringify(next);localStorage.setItem(profileKey(profileId,"watch-progress"),value);localStorage.setItem("slx-watch-progress",value);window.dispatchEvent(new CustomEvent("slx-watch-progress-changed",{detail:next}))}
function removeWatchProgress(profileId:string,itemId:string){const next=readWatchProgress(profileId).filter(entry=>entry.item.id!==itemId);const value=JSON.stringify(next);localStorage.setItem(profileKey(profileId,"watch-progress"),value);localStorage.setItem("slx-watch-progress",value);window.dispatchEvent(new CustomEvent("slx-watch-progress-changed",{detail:next}))}
function extractSubtitles(input:any,base?:string):SubtitleSource[]{const result:SubtitleSource[]=[];const add=(value:any,index:number)=>{if(!value)return;const raw=typeof value==="string"?value:value.url||value.src||value.file||value.path||value.subtitle_url;if(typeof raw!=="string"||!raw.trim())return;let src=raw.trim();try{src=new URL(src,base||location.href).href}catch{return}if(!/^https?:/i.test(src))return;const language=String(typeof value==="object"?(value.language||value.lang||value.code||""):"").toLowerCase()||"und";const label=String(typeof value==="object"?(value.label||value.name||value.title||""):"")||`${language==="und"?"Altyazı":language.toUpperCase()} ${index+1}`;if(!result.some(x=>x.src===src))result.push({src,label,language})};const values=[input?.subtitles,input?.subtitle,input?.subtitle_url,input?.info?.subtitles,input?.info?.subtitle,input?.info?.subtitle_url,input?.movie_data?.subtitles].flatMap(value=>Array.isArray(value)?value:[value]);values.forEach(add);return result}

function useSessionPanelScroll(selector:string,key:string,enabled=true){
  useLayoutEffect(()=>{
    if(!enabled)return;
    const panel=document.querySelector(selector) as HTMLElement|null;
    if(!panel)return;
    const save=()=>sessionStorage.setItem(key,String(panel.scrollTop));
    const restore=()=>{panel.scrollTop=Number(sessionStorage.getItem(key)||0)};
    restore();
    requestAnimationFrame(()=>requestAnimationFrame(restore));
    const onVisibility=()=>{if(document.visibilityState==="hidden")save()};
    panel.addEventListener("scroll",save,{passive:true});
    window.addEventListener("pagehide",save);
    document.addEventListener("visibilitychange",onVisibility);
    return()=>{save();panel.removeEventListener("scroll",save);window.removeEventListener("pagehide",save);document.removeEventListener("visibilitychange",onVisibility)};
  },[selector,key,enabled]);
}
