const alphabetic=(a:string,b:string)=>a.localeCompare(b,"tr",{sensitivity:"base",numeric:true});
const displayTitle=(value?:string|null)=>(value||"").replace(/\s*[\[(](?:19|20)\d{2}[\])]/g,"").replace(/\s{2,}/g," ").trim();
const cleanOverview=(...values:Array<unknown>)=>values.map(value=>String(value||"").trim()).find(value=>{const normalized=value.toLocaleLowerCase("tr").replace(/\s+/g," ");return value&&!normalized.includes("bilgiler yükleniyor")&&!normalized.includes("information is loading")&&!/^loading\b/.test(normalized)})||"";
