const titleKey=(value?:string|null)=>(value||"").toLocaleLowerCase("tr").replace(/\[[^\]]*]|\([^)]*\)|\b(?:19|20)\d{2}\b|\b(?:4k|uhd|fhd|hd|sd|tr|dublaj|altyazılı|multi)\b/gi," ").replace(/[^a-z0-9çğıöşü]+/gi," ").trim();
const collapseMediaSources=(rows:Media[])=>{const groups=new Map<string,Media[]>();rows.forEach(item=>{if(item.kind==="live")return;const key=`${item.kind}:${titleKey(item.name)}`;if(titleKey(item.name))groups.set(key,[...(groups.get(key)||[]),item])});const used=new Set<string>();return rows.filter(item=>{if(item.kind==="live")return true;const key=`${item.kind}:${titleKey(item.name)}`;if(used.has(key))return false;used.add(key);return true}).map(item=>{if(item.kind==="live")return item;const sources=groups.get(`${item.kind}:${titleKey(item.name)}`)||[item];return sources.length>1?{...item,sources}:item})};
const tmdbLibraryKey=(kind:Kind,source:Media[])=>`tmdb-cache-v4:${getLocale()}:${kind}:${source.length}:${source[0]?.id||"0"}:${source.at(-1)?.id||"0"}`;
async function apiJSON<T=any>(url:string,init?:RequestInit):Promise<T>{const response=await fetch(url,init);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`API ${response.status} hatası verdi`);return data as T}
const TMDB_TIMEOUT_MS=20000,TMDB_CONCURRENCY=4,TMDB_CHUNK=12;
const tmdbCache=new Map<string,any>();
const tmdbInFlight=new Map<string,Promise<any[]>>();
let tmdbActiveRequests=0;const tmdbQueue:Array<()=>void>=[];
function tmdbDrain(){while(tmdbActiveRequests<TMDB_CONCURRENCY&&tmdbQueue.length){const job=tmdbQueue.shift()!;tmdbActiveRequests++;job()}}
function tmdbEnqueue<T>(task:()=>Promise<T>):Promise<T>{return new Promise((resolve,reject)=>{tmdbQueue.push(()=>{task().then(resolve,reject).finally(()=>{tmdbActiveRequests--;tmdbDrain()})});tmdbDrain()})}
async function fetchTmdbChunk(chunk:Media[],signal?:AbortSignal):Promise<any[]>{
  const key=chunk.map(x=>x.id).sort().join(",");const existing=tmdbInFlight.get(key);if(existing)return existing;
  const promise=(async()=>{const controller=new AbortController();const onAbort=()=>controller.abort();signal?.addEventListener("abort",onAbort);const timer=setTimeout(()=>controller.abort(),TMDB_TIMEOUT_MS);try{const response=await fetch("/api/tmdb",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({items:chunk.map(x=>({id:x.id,name:x.name,kind:x.kind}))}),signal:controller.signal});if(!response.ok)return[];const data=await response.json();return data.results||[]}catch{return[]}finally{clearTimeout(timer);signal?.removeEventListener("abort",onAbort)}})();
  tmdbInFlight.set(key,promise);promise.finally(()=>tmdbInFlight.delete(key));return promise;
}
async function enrichAll(source:Media[],onPage:(rows:any[],done:number,total:number)=>void,signal?:AbortSignal){
  const cachedRows:any[]=[];const toFetch:Media[]=[];for(const item of source){if(tmdbCache.has(item.id)){const hit=tmdbCache.get(item.id);if(hit)cachedRows.push(hit)}else toFetch.push(item)}
  let done=source.length-toFetch.length;if(cachedRows.length)onPage(cachedRows,done,source.length);if(!toFetch.length)return;
  const chunks:Media[][]=[];for(let i=0;i<toFetch.length;i+=TMDB_CHUNK)chunks.push(toFetch.slice(i,i+TMDB_CHUNK));
  await Promise.all(chunks.map(chunk=>tmdbEnqueue(async()=>{if(signal?.aborted)return;const rows=await fetchTmdbChunk(chunk,signal);if(signal?.aborted)return;rows.forEach((row:any)=>tmdbCache.set(row.playlistId,row));chunk.forEach(item=>{if(!tmdbCache.has(item.id))tmdbCache.set(item.id,null)});done+=chunk.length;onPage(rows,done,source.length)})))
}
async function fetchJSONTimeout(url:string,init:RequestInit={},timeoutMs=TMDB_TIMEOUT_MS){const controller=new AbortController();const outer=init.signal as AbortSignal|undefined;const onAbort=()=>controller.abort();outer?.addEventListener("abort",onAbort);const timer=setTimeout(()=>controller.abort(),timeoutMs);try{const response=await fetch(url,{...init,signal:controller.signal});return await response.json().catch(()=>({}))}finally{clearTimeout(timer);outer?.removeEventListener("abort",onAbort)}}

function libraryDB(){
  // Ayni origin'de birden fazla sekme/baglanti IndexedDB'yi acmaya calisirken tarayici
  // istegi "blocked" durumuna alabiliyor; bu olay icin bir dinleyici olmayinca Promise ne
  // basarili ne hatali sonuclanmadan sonsuza kadar askida kaliyordu ("hazirlaniyor" ekraninda
  // takilma). onblocked'i reddederek ve genel bir zaman asimiyla bu asilma durumunu onluyoruz.
  return new Promise<IDBDatabase>((resolve,reject)=>{
    const req=indexedDB.open("streamlivex-v2",1);
    const timer=setTimeout(()=>reject(new Error("IndexedDB zaman aşımına uğradı")),5000);
    req.onupgradeneeded=()=>req.result.createObjectStore("library");
    req.onsuccess=()=>{clearTimeout(timer);resolve(req.result)};
    req.onerror=()=>{clearTimeout(timer);reject(req.error)};
    req.onblocked=()=>{clearTimeout(timer);reject(new Error("IndexedDB başka bir sekme tarafından bloklandı"))};
  });
}
async function dbSet(key:string,value:unknown){const db=await libraryDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction("library","readwrite");tx.objectStore("library").put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()}
async function dbGet<T>(key:string){const db=await libraryDB();const value=await new Promise<T|undefined>((resolve,reject)=>{const req=db.transaction("library").objectStore("library").get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();return value}
async function dbClear(){const db=await libraryDB();await new Promise<void>((resolve,reject)=>{const tx=db.transaction("library","readwrite");tx.objectStore("library").clear();tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()}

