  const byKey=new Map<string,Media>();media.forEach(x=>{const key=titleKey(x.name);if(key&&!byKey.has(key))byKey.set(key,x)});const mapTrends=(rows:any[],kind:Kind)=>{const used=new Set<string>();return rows.map(t=>{const key=titleKey(t.title||t.name||"");const found=byKey.get(key);if(!found||found.kind!==kind||used.has(key)||watchedIds.includes(found.id))return null;used.add(key);return {...found,name:displayTitle(found.name),tmdbId:t.id,logo:t.poster_path?`https://image.tmdb.org/t/p/w500${t.poster_path}`:found.logo,rating:t.vote_average?.toFixed?.(1)||found.rating,year:(t.release_date||t.first_air_date||"").slice(0,4)||found.year,plot:t.overview||found.plot}}).filter(Boolean) as Media[]};
