function MediaControlCenter({profileId,items}:{profileId:string;items:Media[]}){const [tab,setTab]=useState("health");const [scan,setScan]=useState(0);const [lists,setLists]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem(profileKey(profileId,"custom-lists"))||"[]")}catch{return[]}});const [listName,setListName]=useState("");const [corrections,setCorrections]=useState<Record<string,string>>(()=>{try{return JSON.parse(localStorage.getItem("slx-tmdb-corrections")||"{}")}catch{return{}}});const duplicates=items.length-new Set(items.map(x=>`${x.kind}:${titleKey(x.name)}`)).size;const missing=items.filter(x=>x.kind!=="live"&&!x.logo).length;const startScan=()=>{setScan(1);let n=1;const timer=setInterval(()=>{n+=11;setScan(Math.min(100,n));if(n>=100)clearInterval(timer)},120)};const addList=()=>{const name=listName.trim();if(!name)return;const next=Array.from(new Set([...lists,name]));setLists(next);localStorage.setItem(profileKey(profileId,"custom-lists"),JSON.stringify(next));setListName("")};const exportData=()=>{const keys=Object.keys(localStorage).filter(k=>k.startsWith("slx-"));const data=Object.fromEntries(keys.map(k=>[k,localStorage.getItem(k)]));const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="streamlivex-yedek.json";a.click();URL.revokeObjectURL(a.href)};return <section className="media-center"><header><span>GELİŞMİŞ ARAÇLAR</span><h2>Kütüphane ve yayın merkezi</h2><p>Yayın sağlığı, listeler, eşleştirmeler, performans ve yedekleme tek yerde.</p></header><nav>{[["health","Yayın Sağlığı"],["library","Kütüphane"],["lists","Listem"],["match","TMDB Düzeltme"],["backup","Yedekleme"]].map(([id,label])=><button className={tab===id?"active":""} key={id} onClick={()=>setTab(id)}>{label}</button>)}</nav>{tab==="health"&&<div className="center-panel"><div className="metric-grid"><article><b>{items.filter(x=>x.kind==="live").length}</b><span>Canlı kaynak</span></article><article><b>{items.filter(x=>/\.m3u8/i.test(x.url)).length}</b><span>HLS uyumlu</span></article><article><b>{items.filter(x=>/\.ts($|\?)/i.test(x.url)).length}</b><span>MPEG‑TS</span></article><article><b>{items.filter(x=>/\.mkv|h265|hevc/i.test(x.url+x.name)).length}</b><span>Harici oynatıcı gerekebilir</span></article></div><button onClick={startScan}>Yayın biçimlerini tara</button>{scan>0&&<div className="scanbar"><i style={{width:`${scan}%`}}/><b>{scan}%</b></div>}<p>Oynatıcı HLS, MP4 ve tarayıcı uyumlu MPEG‑TS kaynaklarını sırayla dener; H.265 için VLC aktarımı sunar.</p></div>}{tab==="library"&&<div className="center-panel"><div className="metric-grid"><article><b>{items.length.toLocaleString("tr-TR")}</b><span>Toplam içerik</span></article><article><b>{duplicates}</b><span>Olası tekrar</span></article><article><b>{missing}</b><span>Postersiz VOD</span></article><article><b>{new Set(items.map(x=>x.group)).size}</b><span>Kategori</span></article></div><p>Tekrarlar normalize edilmiş isim ve içerik türüne göre hesaplanır. TMDB önbelleği yalnızca görünür kartları besler.</p></div>}{tab==="lists"&&<div className="center-panel"><div className="list-create"><input value={listName} onChange={e=>setListName(e.target.value)} placeholder="Yeni liste adı"/><button onClick={addList}>Liste oluştur</button></div>{lists.length?<div className="custom-lists">{lists.map(x=><article key={x}><ListVideo size={18}/><b>{x}</b><small>0 içerik · Kartlardaki liste düğmesiyle eklenir</small></article>)}</div>:<p>Henüz özel listeniz yok. “Hafta sonu”, “Ailece” veya “Sonra izle” gibi listeler oluşturun.</p>}</div>}{tab==="match"&&<div className="center-panel"><p>Yanlış eşleşen içerik için IPTV adını ve doğru TMDB kimliğini kaydedin. Bu düzeltme sonraki eşleştirmelerde korunur.</p><div className="correction-form"><input id="corr-name" placeholder="IPTV içerik adı"/><input id="corr-id" placeholder="TMDB ID" inputMode="numeric"/><button onClick={()=>{const name=(document.getElementById("corr-name") as HTMLInputElement)?.value.trim();const id=(document.getElementById("corr-id") as HTMLInputElement)?.value.trim();if(name&&id){const next={...corrections,[titleKey(name)]:id};setCorrections(next);localStorage.setItem("slx-tmdb-corrections",JSON.stringify(next))}}}>Düzeltmeyi kaydet</button></div><b>{Object.keys(corrections).length} kalıcı düzeltme</b></div>}{tab==="backup"&&<div className="center-panel"><p>Profiller, favoriler, izleme geçmişi, özel listeler, ayarlar ve TMDB düzeltmeleri JSON olarak dışa aktarılır.</p><button onClick={exportData}>Tüm verileri yedekle</button><label className="restore-file">Yedeği geri yükle<input type="file" accept="application/json" onChange={e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result));Object.entries(data).forEach(([k,v])=>{if(k.startsWith("slx-")&&typeof v==="string")localStorage.setItem(k,v)});location.reload()}catch{}};reader.readAsText(file)}}/></label></div>}</section>}
