  const groups=Array.from(new Set(items.map(x=>x.group))).sort(alphabetic);const clearHistory=()=>{localStorage.removeItem(profileKey(profileId,"watched"));localStorage.removeItem(profileKey(profileId,"watch-progress"));localStorage.removeItem("slx-watched");localStorage.removeItem("slx-watch-progress");setNotice("Bu profilin izleme geçmişi temizlendi")};
